input.content:
#!/usr/bin/env bash
set -euo pipefail

base=${1:?usage: percentage.sh BASE VALUE}
value=${2:?usage: percentage.sh BASE VALUE}

if [ "$base" -eq 0 ]; then
  echo "error: base must be non-zero" >&2
  exit 2
fi

echo $(( (value - base) * 100 / base ))
